from __future__ import annotations

import os
from typing import Any, Dict, List, Optional

import structlog

from rasa.builder.telemetry.langfuse_integration.langfuse_compat import with_langfuse

structlogger = structlog.get_logger()
LANGFUSE_SESSION_URL_TEMPLATE_ENV_VAR = "LANGFUSE_SESSION_URL_TEMPLATE"


def get_current_trace_context(sender_id: Optional[str] = None) -> Dict[str, str]:
    """Return current Langfuse trace context for attaching to events."""
    try:
        with with_langfuse() as lf:
            if not lf:
                return {}
            langfuse_client = lf.get_client()
            trace_id = langfuse_client.get_current_trace_id()
            if not trace_id:
                return {}

            trace_context: Dict[str, str] = {"langfuse_trace_id": str(trace_id)}

            trace_url: Optional[str] = None
            try:
                trace_url = langfuse_client.get_trace_url(trace_id)
            except TypeError:
                # Some SDK variants expose get_trace_url without arguments.
                trace_url = langfuse_client.get_trace_url()

            if trace_url:
                trace_context["langfuse_trace_url"] = trace_url

            if sender_id:
                session_template = os.getenv(LANGFUSE_SESSION_URL_TEMPLATE_ENV_VAR)
                if session_template:
                    try:
                        trace_context["langfuse_session_url"] = session_template.format(
                            session_id=sender_id,
                            sender_id=sender_id,
                        )
                    except Exception:
                        pass

            return trace_context
    except Exception as e:
        structlogger.debug(
            "langfuse_telemetry.get_current_trace_context.failed",
            error=repr(e),
        )
        return {}


def update_current_trace_for_turn(
    *,
    sender_id: Optional[str],
    message_id: Optional[str],
    user_id: Optional[str] = None,
    assistant_id: Optional[str] = None,
    model_id: Optional[str] = None,
    input_channel: Optional[str] = None,
    tags: Optional[List[str]] = None,
    trace_input: Optional[Any] = None,
    trace_output: Optional[Any] = None,
) -> None:
    """Best-effort update of current trace with turn/conversation grouping."""
    try:
        with with_langfuse() as lf:
            if not lf:
                return
            langfuse_client = lf.get_client()
            metadata: Dict[str, Any] = {
                "sender_id": sender_id,
                "message_id": message_id,
                "assistant_id": assistant_id,
                "model_id": model_id,
                "input_channel": input_channel,
            }
            langfuse_client.update_current_trace(
                session_id=sender_id,
                user_id=user_id,
                input=trace_input,
                output=trace_output,
                metadata=metadata,
                tags=tags or [],
            )
    except Exception as e:
        structlogger.debug(
            "langfuse_telemetry.update_current_trace_for_turn.failed",
            error=repr(e),
        )


def update_current_span_metadata(
    *,
    name: Optional[str] = None,
    metadata: Optional[Dict[str, Any]] = None,
    span_input: Optional[Any] = None,
    span_output: Optional[Any] = None,
) -> None:
    """Best-effort update of current observation/span metadata."""
    try:
        with with_langfuse() as lf:
            if not lf:
                return
            langfuse_client = lf.get_client()
            kwargs: Dict[str, Any] = {}
            if name:
                kwargs["name"] = name
            if metadata:
                kwargs["metadata"] = metadata
            if span_input is not None:
                kwargs["input"] = span_input
            if span_output is not None:
                kwargs["output"] = span_output
            if kwargs:
                langfuse_client.update_current_span(**kwargs)
    except Exception as e:
        structlogger.debug(
            "langfuse_telemetry.update_current_span_metadata.failed",
            error=repr(e),
        )
